  var ex = target[0] - tip[0], ey = target[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: "stop", reason: "invalid error" };
  if (err <= state.tolerancePx) return { action: "verify" };

  var H = state.history || [];
  var n = H.length;
  var start = Math.max(0, n - 12);
  var S00 = 1e-9, S01 = 0, S11 = 1e-9;
  var R00 = 0, R01 = 0, R10 = 0, R11 = 0;
  var used = 0;
  var lastCmdSign = [0, 0], lastZero = [false, false];
  var cntNZ = [0, 0];
  for (var i = start; i < n; i++) {
    var h = H[i];
    if (!h) continue;
    var c = h.command, p = h.applied;
    if (c && p) {
      for (var k = 0; k < 2; k++) {
        if (isFinite(c[k]) && Math.abs(c[k]) > 1e-9) {
          lastCmdSign[k] = c[k] > 0 ? 1 : -1;
          lastZero[k] = !(isFinite(p[k]) && Math.abs(p[k]) > 1e-6);
          cntNZ[k]++;
        }
      }
    }
    if (!p || !h.delta) continue;
    var a = p[0], b = p[1], dx = h.delta[0], dy = h.delta[1];
    if (!isFinite(a) || !isFinite(b) || !isFinite(dx) || !isFinite(dy)) continue;
    if (Math.abs(a) + Math.abs(b) < 1e-9) continue;
    var w = Math.pow(0.85, n - 1 - i);
    S00 += w * a * a; S01 += w * a * b; S11 += w * b * b;
    R00 += w * dx * a; R01 += w * dx * b;
    R10 += w * dy * a; R11 += w * dy * b;
    used++;
