  var sDet = S00 * S11 - S01 * S01;
  var probeNeeded = false;
  var u0 = 0, u1 = 0;
  if (used < 2 || !(sDet > 1e-6 * S00 * S11) || sDet <= 0) {
    probeNeeded = true;
