    var J00 = R00 * iS00 + R01 * iS01;
    var J01 = R00 * iS01 + R01 * iS11;
    var J10 = R10 * iS00 + R11 * iS01;
    var J11 = R10 * iS01 + R11 * iS11;
    var jDet = J00 * J11 - J01 * J10;
    var jScale = Math.abs(J00) + Math.abs(J01) + Math.abs(J10) + Math.abs(J11);
    if (!isFinite(jDet) || !isFinite(jScale) || !(Math.abs(jDet) > 1e-6 * jScale * jScale)) {
      probeNeeded = true;
    } else {
      u0 = (J11 * ex - J01 * ey) / jDet;
      u1 = (-J10 * ex + J00 * ey) / jDet;
      if (!isFinite(u0) || !isFinite(u1)) return { action: "stop", reason: "non-finite solve" };
