      if (lastZero[0] && u0 !== 0 && (u0 > 0 ? 1 : -1) === lastCmdSign[0]) u0 = 0;
      if (lastZero[1] && u1 !== 0 && (u1 > 0 ? 1 : -1) === lastCmdSign[1]) u1 = 0;
      if (Math.abs(u0) < 1e-12 && Math.abs(u1) < 1e-12) {
        probeNeeded = true;
      } else {
        var m = Math.max(Math.abs(u0), Math.abs(u1));
        if (m > 0.1) {
          u0 = u0 * 0.1 / m;
          u1 = u1 * 0.1 / m;
        } else {
          var f = err > 3 * state.tolerancePx ? 0.8 : 0.5;
          u0 *= f; u1 *= f;
        }
        u0 = Math.max(-0.1, Math.min(0.1, u0));
        u1 = Math.max(-0.1, Math.min(0.1, u1));
        return { action: "move", u: [u0, u1] };
      }
