  // (e.g. a channel pinned at a travel limit). Back off by reversing the last command.
  if (k >= 3) {
    var stalled = true;
    for (var j = k - 3; j < k; j++) {
      var hj = valid[j];
      var cn = norm2(hj.applied[0], hj.applied[1]);
      var dn = norm2(hj.delta[0], hj.delta[1]);
      if (cn < 1e-4 || dn >= 0.5) { stalled = false; break; }
    }
