      var ua = -last.applied[0], ub = -last.applied[1];
      var mm = Math.max(Math.abs(ua), Math.abs(ub));
      if (mm > 0.1) { ua *= 0.1 / mm; ub *= 0.1 / mm; }
      ua = Math.max(-0.1, Math.min(0.1, Math.round(ua * 10000) / 10000));
      ub = Math.max(-0.1, Math.min(0.1, Math.round(ub * 10000) / 10000));
      if (!fin(ua) || !fin(ub)) { return { action: 'stop', reason: 'non-finite control' }; }
      return { action: 'move', u: [ua, ub] };
    }
