  var J00 = (p00 * S11 - p01 * S01) / sdet;
  var J01 = (p01 * S00 - p00 * S01) / sdet;
  var J10 = (p10 * S11 - p11 * S01) / sdet;
  var J11 = (p11 * S00 - p10 * S01) / sdet;
  var Jdet = J00 * J11 - J01 * J10;
  if (!fin(Jdet) || Math.abs(Jdet) < 1e-6) {
    return { action: 'move', u: probe };
  }

  // u = inv(J) * e
  var u0 = (J11 * ex - J01 * ey) / Jdet;
  var u1 = (-J10 * ex + J00 * ey) / Jdet;
  if (!fin(u0) || !fin(u1)) {
    return { action: 'move', u: probe };
  }

  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m > 0.1) {
    var s = 0.1 / m;
    u0 *= s;
    u1 *= s;
  } else if (m > 0 && m < 0.01) {
