  u1 = Math.max(-0.1, Math.min(0.1, Math.round(u1 * 10000) / 10000));
  if (!fin(u0) || !fin(u1)) { return { action: 'stop', reason: 'non-finite control' }; }
  return { action: 'move', u: [u0, u1] };
}

function control(state) {
  var tip = state.tip, target = state.target;
  if (!tip || !target) return { action: "stop", reason: "missing tip or target" };
