  var ey = Number(target[1]) - Number(tip[1]);
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: "stop", reason: "invalid error" };
  if (err <= state.tolerancePx) return { action: "verify" };

  var hist = state.history || [];
  var start = Math.max(0, hist.length - 40);
  var M00 = 0, M01 = 0, M11 = 0; // sum c c^T
  var R00 = 0, R01 = 0, R10 = 0, R11 = 0; // sum c_i * d_j  (R[i][j])
  var cnt = 0;
  var used = [0, 0];
  for (var i = start; i < hist.length; i++) {
    var h = hist[i];
    var c = h.applied || h.command;
    var d = h.delta;
    if (!c || !d || c.length !== 2 || d.length !== 2) continue;
    var c0 = Number(c[0]), c1 = Number(c[1]), d0 = Number(d[0]), d1 = Number(d[1]);
    if (!isFinite(c0) || !isFinite(c1) || !isFinite(d0) || !isFinite(d1)) continue;
    M00 += c0 * c0; M01 += c0 * c1; M11 += c1 * c1;
    R00 += c0 * d0; R01 += c0 * d1;
    R10 += c1 * d0; R11 += c1 * d1;
    used[0] += Math.abs(c0); used[1] += Math.abs(c1);
    cnt++;
  }

  var recentMove = 0;
  for (var j = Math.max(0, hist.length - 4); j < hist.length; j++) {
    var dd = hist[j].delta;
    if (dd && dd.length === 2) recentMove += Math.abs(Number(dd[0])) + Math.abs(Number(dd[1]));
  }

  var sgn = (hist.length % 4 < 2) ? 1 : -1;
  var probe = function (k) {
    return k === 0 ? [0.1 * sgn, 0] : [0, 0.1 * sgn];
  };
  var probeChannel = (used[0] <= used[1]) ? 0 : 1;

  if (cnt < 3) return { action: "move", u: probe(probeChannel) };
  if (hist.length >= 4 && recentMove < 0.5 && err > state.tolerancePx * 2) {
    return { action: "move", u: probe(probeChannel) };
  }

  // Solve B = (M + lam I)^-1 R ; pixel-from-channel Jacobian J[a][i] = B[i][a]
  var scale = M00 + M11;
  if (!(scale > 1e-9)) return { action: "move", u: probe(probeChannel) };
