  var A00 = M00 + lam, A01 = M01, A11 = M11 + lam;
  var detA = A00 * A11 - A01 * A01;
  if (!isFinite(detA) || Math.abs(detA) < 1e-18) return { action: "move", u: probe(probeChannel) };
  var I00 = A11 / detA, I01 = -A01 / detA, I11 = A00 / detA;
  var B00 = I00 * R00 + I01 * R10;
  var B01 = I00 * R01 + I01 * R11;
  var B10 = I01 * R00 + I11 * R10;
  var B11 = I01 * R01 + I11 * R11;
  // J (2x2): rows pixel x,y ; cols channel 0,1
  var J00 = B00, J01 = B10, J10 = B01, J11 = B11;
  var detJ = J00 * J11 - J01 * J10;
