function control(state) {
  var tip = state.tip;
  var tgt = state.target;
  var e0 = tgt[0] - tip[0];
  var e1 = tgt[1] - tip[1];
  var err = Math.sqrt(e0 * e0 + e1 * e1);
  if (!isFinite(err)) return { action: 'stop', reason: 'bad measurement' };
  if (err <= state.tolerancePx) return { action: 'verify' };
  if (state.maxActions && state.step >= state.maxActions) {
    return { action: 'stop', reason: 'action budget reached' };
  }
  var h = state.history || [];
  var start = Math.max(0, h.length - 12);
  var S00 = 0, S01 = 0, S11 = 0;
  var N00 = 0, N01 = 0, N10 = 0, N11 = 0;
  var cnt = 0;
  var lastCmd = null;
  var blocked = [false, false];
  for (var i = start; i < h.length; i++) {
    var rec = h[i];
    var c = rec.applied || rec.command;
    var d = rec.delta;
    if (!c || !d || !rec.command) continue;
    var c0 = Number(c[0]), c1 = Number(c[1]);
    var d0 = Number(d[0]), d1 = Number(d[1]);
    if (!isFinite(c0) || !isFinite(c1) || !isFinite(d0) || !isFinite(d1)) continue;
    cnt++;
    S00 += c0 * c0; S01 += c0 * c1; S11 += c1 * c1;
    N00 += c0 * d0; N01 += c0 * d1; N10 += c1 * d0; N11 += c1 * d1;
    lastCmd = rec.command;
  }
  // channels that were recently limited at a boundary (commanded but not applied)
  if (h.length > 0) {
    var last = h[h.length - 1];
    if (last.command && last.applied) {
      for (var k = 0; k < 2; k++) {
        if (Math.abs(Number(last.command[k])) > 0.02 &&
            Math.abs(Number(last.applied[k])) < 0.5 * Math.abs(Number(last.command[k]))) {
          blocked[k] = true;
        }
      }
    }
  }
  var lastSign = [1, 1];
  if (lastCmd) {
    lastSign[0] = Number(lastCmd[0]) >= 0 ? 1 : -1;
    lastSign[1] = Number(lastCmd[1]) >= 0 ? 1 : -1;
  }
  var energy = S00 + S11;
  var lam = 1e-3 * energy + 1e-12;
  var M00 = S00 + lam, M01 = S01, M11 = S11 + lam;
  var detM = M00 * M11 - M01 * M01;
  var ok = cnt >= 2 && energy > 1e-6 && isFinite(detM) && detM > 1e-12;
  var u = null;
  if (ok) {
    var I00 = M11 / detM, I01 = -M01 / detM, I11 = M00 / detM;
    var JT00 = I00 * N00 + I01 * N10;
    var JT01 = I00 * N01 + I01 * N11;
    var JT10 = I01 * N00 + I11 * N10;
    var JT11 = I01 * N01 + I11 * N11;
    // J maps command -> delta: delta = J * u
    var J00 = JT00, J01 = JT10, J10 = JT01, J11 = JT11;
    var detJ = J00 * J11 - J01 * J10;
    var scaleJ = (Math.abs(J00) + Math.abs(J01)) * (Math.abs(J10) + Math.abs(J11));
    if (isFinite(detJ) && Math.abs(detJ) > 1e-6 * scaleJ + 1e-12) {
      var u0 = (J11 * e0 - J01 * e1) / detJ;
      var u1 = (-J10 * e0 + J00 * e1) / detJ;
      if (isFinite(u0) && isFinite(u1)) u = [u0, u1];
    }
  }
  if (u === null) {
    // probe: excite the less-used channel, reversing a channel that is stuck at a boundary
    var ch = (S00 <= S11) ? 0 : 1;
    var sgn = -lastSign[ch];
    if (lastCmd === null) sgn = 1;
    var pu = [0, 0];
    pu[ch] = 0.1 * sgn;
    return { action: 'move', u: pu };
  }
  // handle boundary-blocked channels: do not keep pushing into the limit
  for (var b = 0; b < 2; b++) {
    if (blocked[b] && u[b] * lastSign[b] > 0) {
      u[b] = -0.05 * lastSign[b];
    }
  }
  var m = Math.max(Math.abs(u[0]), Math.abs(u[1]));
  if (m > 0.1) {
    u[0] = u[0] * 0.1 / m;
    u[1] = u[1] * 0.1 / m;
  } else if (m > 0 && m < 0.02) {
    u[0] = u[0] * 0.02 / m;
    u[1] = u[1] * 0.02 / m;
  }
  if (!isFinite(u[0]) || !isFinite(u[1])) {
    return { action: 'stop', reason: 'non-finite step' };
  }
  return { action: 'move', u: [u[0], u[1]] };
}
